mapper.select:
select pp.P_Id as pId, pp.P_Name as pName, concat(pp.province, pp.city) as affiliatedArea, pp.P_Type as pType, pp.P_Build_Model as pBuildModel, pp.P_Total_Duration as pTotalDuration, pp.P_Scale_Describe as pScaleDescribe, pp.P_Actual_Start_Time as pActualStartTime, pp.P_Plan_Complete_Date as pPlanCompleteDate, pp.P_Competent_Department as pCompetentDepartment, coalesce(invAgg.plannedForLastQuarter, 0) as plannedForLastQuarter, coalesce(invAgg.plannedForThisQuarter, 0) as plannedForThisQuarter, mn.completedlastquarter as completedLastQuarter, coalesce(tifAgg.completedThisQuarter, 0) as completedThisQuarter, mn.paylastquarter as payLastQuarter, coalesce(tifAgg.payThisQuarter, 0) as payThisQuarter, mn.imageprogress as imageProgress, coalesce(invAgg.firstQuarterTarget, 0) as firstQuarterTarget, coalesce(invAgg.secondQuarterTarget, 0) as secondQuarterTarget, coalesce(invAgg.thirdQuarterTarget, 0) as thirdQuarterTarget, coalesce(invAgg.fourthQuarterTarget, 0) as fourthQuarterTarget from t_information_filling mn left join pre_project pp ON mn.P_Id = pp.P_Id left join ( select ipv.P_Id, ipv.Ipv_Declare_Year as ipvDeclareYear, sum(case when ims.Ims_Month in
#{month}
then ims.Ims_Planned_Inv else 0 END) as plannedForLastQuarter, sum(case when ims.Ims_Month in
#{month}
then ims.Ims_Planned_Inv else 0 END) as plannedForThisQuarter, sum(case when ims.Ims_Month in (1,2,3) then ims.Ims_Planned_Inv else 0 END) as firstQuarterTarget, sum(case when ims.Ims_Month in (4,5,6) then ims.Ims_Planned_Inv else 0 END) as secondQuarterTarget, sum(case when ims.Ims_Month in (7,8,9) then ims.Ims_Planned_Inv else 0 END) as thirdQuarterTarget, sum(case when ims.Ims_Month in (10,11,12) then ims.Ims_Planned_Inv else 0 END) as fourthQuarterTarget from inv_plan_year ipv left join inv_monthly_schedule ims on ipv.ipv_id = ims.ipv_id group by ipv.P_Id, ipv.Ipv_Declare_Year ) invAgg on mn.P_Id = invAgg.P_Id and mn.Reporting_Year = invAgg.ipvDeclareYear left join ( select tif.P_Id, tif.Reporting_Year, sum(tif.completethequarter) as completedThisQuarter, sum(tif.payforthequarter) as payThisQuarter from t_information_filling tif where tif.Reporting_Month in
#{month}
group by tif.P_Id, tif.Reporting_Year ) tifAgg on tifAgg.P_Id = mn.P_Id and mn.Reporting_Year = tifAgg.Reporting_Year
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.creattime desc
